	workflow, _ := s.repository.GetWorkflowConfig(r.Context())
	anonymousMCP := true
	if err := s.repository.Pool().QueryRow(r.Context(), `SELECT value FROM system_settings WHERE key = 'mcp'`).Scan(&raw); err == nil {
